#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

# Nothing here is written to a .env file: these values are secrets for CI only.
ENV_FILE=/dev/null
REPO_EXPECTED="meddlin/composition"
ENV_NAME="release"
REQUIRED_SECRETS=(CSC_LINK CSC_KEY_PASSWORD APPLE_API_KEY_P8 APPLE_API_KEY_ID APPLE_API_ISSUER)

if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  echo "This wizard needs the GitHub CLI, signed in: run 'gh auth login' and re-run." >&2
  exit 1
fi
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner)
if [[ "$REPO" != "$REPO_EXPECTED" ]]; then
  echo "Run this from a checkout of $REPO_EXPECTED (gh sees: $REPO)." >&2
  exit 1
fi

# set_env_secret NAME reads the value from stdin and sets it on the "release" environment.
# (The library's set_secret sets repo-level secrets; the workflow reads environment ones.)
set_env_secret() {
  local name="$1"
  if gh secret set "$name" --env "$ENV_NAME" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s secret %s on the %s environment\n' "$GREEN" "$RESET" "$name" "$ENV_NAME"
  else
    SKIPPED+=("secret $name (gh secret set $name --env $ENV_NAME)")
    warn "couldn't set $name; see the summary at the end"
  fi
}

# expand_path turns a leading ~ into $HOME, so pasted paths like ~/.private_keys/x work.
expand_path() { printf '%s' "${1/#\~/$HOME}"; }

banner "Release workflow secrets for $REPO"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Create the 'release' environment"
say "The release workflow reads its signing secrets from a GitHub environment"
say "named '$ENV_NAME', so only that workflow can see them."
if gh api -X PUT "repos/$REPO/environments/$ENV_NAME" --silent >/dev/null 2>&1; then
  printf '  %s✓ environment%s %s exists\n' "$GREEN" "$RESET" "$ENV_NAME"
else
  warn "couldn't create it through the API (this needs admin access to the repo)."
  open_url "https://github.com/$REPO/settings/environments/new"
  step "Name it '$ENV_NAME' and click Configure environment."
  pause "Press Enter once it exists."
fi
printf '\n'
say "Optional: make each release wait for your approval click."
open_url "https://github.com/$REPO/settings/environments"
step "Open '$ENV_NAME' > tick 'Required reviewers' > add yourself > Save protection rules."
pause "Press Enter when done (or to skip)."

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Signing certificate  →  CSC_LINK, CSC_KEY_PASSWORD"
say "A CI runner has no keychain, so the certificate and its private key travel as a .p12."
{ open -a "Keychain Access" >/dev/null 2>&1; } || true
step "Keychain Access > click 'login' (sidebar) > 'My Certificates' tab."
step "Right-click 'Developer ID Application: Darrien Rushing (49W52J9ZLN)' > Export."
step "Format: Personal Information Exchange (.p12). Save it, for example, to your Desktop."
step "Pick a strong password when asked, and keep it in your password manager."
step "If macOS asks for your login password, that is your Mac account password."
note "Export the certificate row, with the key nested under it, not the key alone."
printf '\n'
while true; do
  ask P12_INPUT "Path to the .p12 (drag the file into this window):"
  P12_PATH=$(expand_path "${P12_INPUT//\'/}")
  P12_PATH="${P12_PATH%% }"
  [[ -f "$P12_PATH" ]] && break
  warn "no file at: $P12_PATH"
done
ask_secret P12_PASSWORD "The password you set for the .p12:"
# Check the password the way electron-builder will use it: import into a throwaway keychain.
CHECK_KC="$(mktemp -u).keychain-db"
P12_OK=0
if security create-keychain -p wizard "$CHECK_KC" >/dev/null 2>&1; then
  P12_ERR=$(security import "$P12_PATH" -k "$CHECK_KC" -P "$P12_PASSWORD" 2>&1 >/dev/null) && P12_OK=1
  security delete-keychain "$CHECK_KC" >/dev/null 2>&1 || true
else
  P12_ERR="couldn't create a temporary keychain"
fi
if (( P12_OK )); then
  printf '  %s✓ password opens the .p12%s\n' "$GREEN" "$RESET"
else
  warn "macOS couldn't import the .p12 with that password:"
  note "  ${P12_ERR}"
  confirm "Upload it anyway?" || { echo "Stopped. Re-run when you have the right password." >&2; exit 1; }
fi
base64 -i "$P12_PATH" | set_env_secret CSC_LINK
printf '%s' "$P12_PASSWORD" | set_env_secret CSC_KEY_PASSWORD
printf '\n'
if confirm "Delete the .p12 from disk now? (it can sign as you; keep a copy in your password manager first)"; then
  rm -f "$P12_PATH"
  printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$P12_PATH"
fi

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Notarization key  →  APPLE_API_KEY_P8, APPLE_API_KEY_ID, APPLE_API_ISSUER"
say "This is the App Store Connect API key you use for local notarization."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Team Keys tab. Your existing key (for example 'composition-notarize') is listed there."
step "Key ID is in the key's row. Issuer ID is at the top of the page."
step "Apple only lets you download the .p8 once. If you still have it (try ~/.private_keys/),"
say "  reuse it. If not, click + to make a new key with the Developer role and download it."
printf '\n'
while true; do
  ask P8_INPUT "Path to the AuthKey_XXXXXXXXXX.p8:"
  P8_PATH=$(expand_path "${P8_INPUT//\'/}")
  if [[ ! -f "$P8_PATH" ]]; then warn "no file at: $P8_PATH"; continue; fi
  if ! grep -q 'BEGIN PRIVATE KEY' "$P8_PATH"; then warn "that doesn't look like a .p8 private key"; continue; fi
  break
done
ask APPLE_KEY_ID "Key ID (10 characters):"
ask APPLE_ISSUER "Issuer ID (a UUID):"
if [[ "$(basename "$P8_PATH")" != "AuthKey_${APPLE_KEY_ID}.p8" ]]; then
  warn "the file name is $(basename "$P8_PATH"), which doesn't match Key ID $APPLE_KEY_ID."
  confirm "Continue anyway?" || { echo "Stopped. Check the Key ID against the file name." >&2; exit 1; }
fi
set_env_secret APPLE_API_KEY_P8 < "$P8_PATH"
printf '%s' "$APPLE_KEY_ID" | set_env_secret APPLE_API_KEY_ID
printf '%s' "$APPLE_ISSUER" | set_env_secret APPLE_API_ISSUER

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Check that GitHub has all five"
LISTED=$(gh secret list --env "$ENV_NAME" --repo "$REPO" 2>/dev/null | awk '{print $1}' || true)
ALL_PRESENT=1
for name in "${REQUIRED_SECRETS[@]}"; do
  if grep -qx "$name" <<<"$LISTED"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    printf '  %s✗%s %s is missing\n' "$RED" "$RESET" "$name"
    ALL_PRESENT=0
  fi
done
printf '\n'
if (( ALL_PRESENT )); then
  say "All set. To cut a release (see docs/deployment/manual-build-release.md):"
  note "  git checkout main && git pull"
  note "  git tag desktop-v0.1.0 && git push origin desktop-v0.1.0"
  note "Settle the provisional appId in apps/desktop/electron-builder.yml and merge the icon change first."
else
  warn "re-run this wizard to fill in what's missing."
fi
pause "Press Enter to finish."

finish
